if total >= 40:
    print("总价：", total)
    print("你可以使用满减优惠")
else:
    print("总价：", total)
    print("还没有达到优惠门槛")

def get_total(price, count):
    return price * count

menu = {"name": "午餐便当", "price": 18}
count = int(input("请输入购买份数："))
total = get_total(menu["price"], count)
print("总价：", total)
